//! Generated query functions for the in-crate example schema
//! (`src/sqlite_rs/sqlite/`). Regenerated by `cargo xtask sql gen`.

#[derive(Debug, PartialEq)]
pub struct ItemSummary {
    pub id: i64,
    pub name: String,
}

pub type ExternalRange = std::ops::Range<i64>;

pub mod queries {
    include!("sqlite/gen.rs");
}

#[tokio::test]
async fn all_query_destinations_and_row_shapes() -> crate::SqlResult<()> {
    use crate::{Json, Sql};
    use queries::*;
    let database = crate::test_support::db(MIGRATIONS).expect("test database");
    // The derived history table name is what a unit applies itself under
    // when it shares a database; here it is the ephemeral database's own.
    assert_eq!(MIGRATION_TABLE, "_sqlite_rs_migrations");
    database
        .apply_migrations(MIGRATION_TABLE, MIGRATIONS)
        .await?;
    let inserted = insert_returning(&database, "first".into()).await?;
    assert_eq!(
        inserted,
        InsertReturningRow {
            id: 1,
            name: "first".into()
        }
    );
    assert_eq!(
        get_summary(&database, 1).await?,
        Some(ItemSummary {
            id: 1,
            name: "first".into()
        })
    );
    assert_eq!(get_summary(&database, 2).await?, None);
    assert_eq!(get_range(&database, 1).await?, Some(1..2));
    assert_eq!(get_range(&database, 2).await?, None);
    let mut transaction = database.begin_write().await?;
    let savepoint = transaction.savepoint("import").await?;
    assert_eq!(insert_returning(&savepoint, "second".into()).await?.id, 2);
    assert_eq!(
        get_summary(&savepoint, 2).await?,
        Some(ItemSummary {
            id: 2,
            name: "second".into()
        })
    );
    savepoint.release().await?;
    assert_eq!(
        names_by_ids(&transaction, Json(vec![1, 2])).await?,
        vec!["first", "second"]
    );
    transaction.commit().await?;
    let snapshot = database.begin_read().await?;
    assert_eq!(
        get_summary(&snapshot, 2).await?,
        Some(ItemSummary {
            id: 2,
            name: "second".into()
        })
    );
    assert!(names_by_ids(&snapshot, Json(Vec::new())).await?.is_empty());
    let mut sql = Sql::new("SELECT id, name, payload, score FROM items WHERE id = ");
    sql.bind(1_i64);
    assert_eq!(
        sql.query(&snapshot).await?.one::<GetItemRow>()?,
        get_item(&snapshot, 1).await?.expect("item")
    );
    snapshot.rollback().await?;
    Ok(())
}
